begin;
create table if not exists public.arkanis_potions (id text primary key, name text not null unique, data jsonb not null);
alter table public.arkanis_potions enable row level security;
revoke all on public.arkanis_potions from public, anon, authenticated;
grant select on public.arkanis_potions to authenticated;
drop policy if exists arkanis_potions_read on public.arkanis_potions;
create policy arkanis_potions_read on public.arkanis_potions for select to authenticated using(true);
insert into public.arkanis_potions(id,name,data)
select value->>'id',value->>'name',value from jsonb_array_elements($potions$[{"id": "potion-001", "number": 1, "level": 1, "name": "Poção da Cicatrização", "ingredients": ["Pérola Branca", "Seiva de Samaúma Ancestral"], "effect": "recupera 1d8 PV imediatamente e mais 1d4 PV no início do próximo turno.", "duration": "imediata, com regeneração durante 1 rodada.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-001.svg"}, {"id": "potion-002", "number": 2, "level": 1, "name": "Poção da Sombra Velada", "ingredients": ["Pérola Negra", "Tinta de Kraken"], "effect": "+1d4 em Agilidade para testes de furtividade; em áreas de penumbra, também recebe +2 nos testes para se esconder.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-002.svg"}, {"id": "potion-003", "number": 3, "level": 1, "name": "Poção do Chamado Profundo", "ingredients": ["Concha Abissal", "Pó de Osso Espectral"], "effect": "permite ouvir espíritos aquáticos em um raio de 10 metros. Recebe +1d4 em Sensibilidade para percebê-los.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-003.svg"}, {"id": "potion-004", "number": 4, "level": 1, "name": "Poção da Brasa Marinha", "ingredients": ["Coral Vermelho", "Flor de Magma"], "effect": "envolve uma arma em chamas mágicas, causando +1d6 de dano de fogo em ataques bem-sucedidos, inclusive debaixo d'água.", "duration": "3 rodadas.", "use": "revestimento de arma.", "icon": "/icons/arkanis/potions/potion-004.svg"}, {"id": "potion-005", "number": 5, "level": 1, "name": "Poção do Predador", "ingredients": ["Dente de Tubarão", "Presa de Onça Fantasma"], "effect": "+1d4 em Força e +1d4 em Sensibilidade para rastrear criaturas.", "duration": "5 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-005.svg"}, {"id": "potion-006", "number": 6, "level": 1, "name": "Poção dos Pulmões Marinhos", "ingredients": ["Escama de Ser Marinho", "Raiz de Mangue Negro"], "effect": "permite respirar debaixo d'água e concede +1d4 em Resistência enquanto estiver submerso.", "duration": "30 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-006.svg"}, {"id": "potion-007", "number": 7, "level": 1, "name": "Poção do Luar Revelador", "ingredients": ["Escama de Peixe-Lua", "Flor da Lua Silvestre"], "effect": "ilumina rastros e inscrições mágicas em um raio de 5 metros. Concede +1d4 em Sensibilidade para identificá-los.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-007.svg"}, {"id": "potion-008", "number": 8, "level": 1, "name": "Poção da Paralisia Breve", "ingredients": ["Espinho de Baiacu", "Veneno de Escorpião Dourado"], "effect": "causa 1d6 de dano tóxico. Se o alvo falhar no teste de Resistência CD 12, fica paralisado por 1 rodada, sem poder agir ou se mover.", "duration": "1 rodada após o contato.", "use": "arremessar contra um alvo a até 6 metros ou aplicar em uma arma. Exige acerto.", "icon": "/icons/arkanis/potions/potion-008.svg"}, {"id": "potion-009", "number": 9, "level": 1, "name": "Poção da Centelha", "ingredients": ["Núcleo de Água-viva", "Cristal de Tempestade"], "effect": "permite lançar uma descarga elétrica de 1d8 de dano contra um alvo a até 6 metros, mediante ataque contra seus Reflexos.", "duration": "3 rodadas, com uma descarga disponível no total.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-009.svg"}, {"id": "potion-010", "number": 10, "level": 1, "name": "Poção da Mente Serena", "ingredients": ["Lótus Celeste", "Folha de Bordo Dourado"], "effect": "+1d4 em Presença para testes de autocontrole e resistência ao medo.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-010.svg"}, {"id": "potion-011", "number": 11, "level": 1, "name": "Poção do Vigor das Águas", "ingredients": ["Orvalho de Vitória-Régia", "Alga de Espuma Dourada"], "effect": "recupera 1d8 PV e 1d6 Mana.", "duration": "imediata.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-011.svg"}, {"id": "potion-012", "number": 12, "level": 1, "name": "Poção do Terror Noturno", "ingredients": ["Cogumelo do Lamento", "Essência de Pesadelo"], "effect": "o alvo testa Resistência CD 12. Na falha, sofre -1d4 em Sensibilidade e -2 nos ataques enquanto vê alucinações assustadoras.", "duration": "3 rodadas.", "use": "arremessar a até 6 metros. Exige acerto.", "icon": "/icons/arkanis/potions/potion-012.svg"}, {"id": "potion-013", "number": 13, "level": 1, "name": "Poção da Pele Mutável", "ingredients": ["Lodo de Bruxa", "Pó de Asa de Borboleta Imperial"], "effect": "altera cor da pele, cabelos e pequenos traços físicos. Concede +1d4 em Presença para testes de atuação e disfarce.", "duration": "20 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-013.svg"}, {"id": "potion-014", "number": 14, "level": 1, "name": "Poção dos Pés Velozes", "ingredients": ["Semente de Guaraná Místico", "Capim de Vento"], "effect": "+1d4 em Agilidade e +2 metros de deslocamento terrestre.", "duration": "5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-014.svg"}, {"id": "potion-015", "number": 15, "level": 1, "name": "Poção da Pele-Rocha", "ingredients": ["Bolota de Carvalho Milenar", "Pó de Granito Vivo"], "effect": "+1d4 em Resistência e redução de 2 pontos do dano físico recebido por ataque, após a armadura.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-015.svg"}, {"id": "potion-016", "number": 16, "level": 1, "name": "Poção da Limpeza Arcana", "ingredients": ["Seiva de Bétula Prateada", "Flor de Sal Azul"], "effect": "remove um efeito mágico negativo de nível I, como uma maldição fraca, envenenamento alquímico ou confusão mágica.", "duration": "imediata.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-016.svg"}, {"id": "potion-017", "number": 17, "level": 1, "name": "Poção do Instante Dilatado", "ingredients": ["Areia de Ampulheta Viva", "Engrenagem de Relógio Fantasma"], "effect": "+1d4 diretamente em Reflexos, sem modificar Agilidade ou Sensibilidade.", "duration": "3 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-017.svg"}, {"id": "potion-018", "number": 18, "level": 1, "name": "Poção da Miragem Colorida", "ingredients": ["Cristal de Miragem", "Pó de Arco-Íris"], "effect": "cria imagens ilusórias simples e concede +1d4 em Presença para testes de enganação e atuação.", "duration": "5 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-018.svg"}, {"id": "potion-019", "number": 19, "level": 1, "name": "Poção da Queda Suave", "ingredients": ["Pena de Grifo", "Pena de Avestruz Celeste"], "effect": "reduz em 1d10 o dano de cada queda e concede +1d4 em Agilidade para manobras aéreas.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-019.svg"}, {"id": "potion-020", "number": 20, "level": 1, "name": "Poção da Luz Serena", "ingredients": ["Cogumelo Bioluminescente", "Vidro de Vitral Sagrado"], "effect": "cria luz mágica em um raio de 6 metros e concede +1d4 em Sensibilidade para perceber objetos e movimentos na escuridão.", "duration": "30 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-020.svg"}, {"id": "potion-021", "number": 21, "level": 1, "name": "Poção da Renovação", "ingredients": ["Cinza de Fênix", "Fruto da Primavera Eterna"], "effect": "recupera 2d8 PV e concede +1d4 em Resistência.", "duration": "cura imediata; bônus por 3 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-021.svg"}, {"id": "potion-022", "number": 22, "level": 1, "name": "Poção do Gelo Vivo", "ingredients": ["Flor de Gelo Eterno", "Lágrima de Gigante de Gelo"], "effect": "permite um ataque congelante de 1d8 de dano a até 6 metros. O alvo atingido perde 2 metros de deslocamento na próxima rodada se falhar em Resistência CD 12.", "duration": "ataque imediato; lentidão por 1 rodada.", "use": "arremessar.", "icon": "/icons/arkanis/potions/potion-022.svg"}, {"id": "potion-023", "number": 23, "level": 1, "name": "Poção da Faísca Cósmica", "ingredients": ["Fragmento de Estrela Cadente", "Núcleo de Cometa Encantado"], "effect": "causa 1d10 de dano mágico luminoso em um alvo.", "duration": "imediata.", "use": "arremessar a até 8 metros.", "icon": "/icons/arkanis/potions/potion-023.svg"}, {"id": "potion-024", "number": 24, "level": 1, "name": "Poção do Sono Guiado", "ingredients": ["Raiz de Cipó dos Sonhos", "Poeira de Sonho"], "effect": "induz sono voluntário e permite controlar parcialmente os sonhos. Concede +1d4 em Inteligência para testes realizados dentro deles.", "duration": "até 1 hora de sono.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-024.svg"}, {"id": "potion-025", "number": 25, "level": 1, "name": "Poção da Leveza Etérea", "ingredients": ["Pó de Fada", "Gota de Nuvem Sólida"], "effect": "+1d4 em Agilidade e redução de 1d8 de dano por queda. Permite saltar o dobro da altura normal.", "duration": "5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-025.svg"}, {"id": "potion-026", "number": 26, "level": 1, "name": "Poção da Voz do Bosque", "ingredients": ["Raiz de Fungo-Rei", "Resina de Árvore-Sussurro"], "effect": "permite compreender mensagens de plantas e fungos. Concede +1d4 em Sensibilidade para perceber informações transmitidas pela vegetação.", "duration": "15 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-026.svg"}, {"id": "potion-027", "number": 27, "level": 1, "name": "Poção da Barreira Nula", "ingredients": ["Cristal do Vazio", "Pó de Tijolo Rúnico"], "effect": "cria uma barreira pessoal que absorve até 1d8 de dano mágico total antes de desaparecer.", "duration": "3 rodadas ou até esgotar sua absorção.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-027.svg"}, {"id": "potion-028", "number": 28, "level": 1, "name": "Poção da Escuridão", "ingredients": ["Flor do Eclipse Negro", "Gema de Pedra-Sombra"], "effect": "produz escuridão mágica em um raio de 3 metros. Criaturas sem capacidade de enxergar através dela sofrem -2 nos ataques.", "duration": "3 rodadas.", "use": "arremessar a até 8 metros.", "icon": "/icons/arkanis/potions/potion-028.svg"}, {"id": "potion-029", "number": 29, "level": 1, "name": "Poção da Alma Protegida", "ingredients": ["Lágrima de Unicórnio", "Cinza de Vela Funerária"], "effect": "+1d4 em Presença para resistir a efeitos espirituais e reduz em 1d6 o primeiro dano espiritual recebido.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-029.svg"}, {"id": "potion-030", "number": 30, "level": 1, "name": "Poção do Eco do Passado", "ingredients": ["Cera de Vela Oracular", "Pedra de Túmulo Esquecido"], "effect": "revela fragmentos de um acontecimento ocorrido no local nas últimas 24 horas. Concede +1d4 em Inteligência para interpretar a visão.", "duration": "5 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-030.svg"}, {"id": "potion-031", "number": 31, "level": 2, "name": "Poção da Cura Emocional", "ingredients": ["Poção da Cicatrização", "Lágrima de Ninfa Fluvial"], "effect": "recupera 2d8 PV, encerra um efeito de medo de nível I e concede +1d6 em Presença para testes de autocontrole.", "duration": "cura imediata; bônus por 10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-031.svg"}, {"id": "potion-032", "number": 32, "level": 2, "name": "Poção da Presença Apagada", "ingredients": ["Poção da Sombra Velada", "Musgo de Cripta"], "effect": "+1d6 em Agilidade para furtividade. O usuário fica invisível à visão comum enquanto estiver em sombra ou penumbra e não pode ser detectado por habilidades comuns de percepção vital.", "duration": "5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-032.svg"}, {"id": "potion-033", "number": 33, "level": 2, "name": "Poção do Diálogo dos Afogados", "ingredients": ["Poção do Chamado Profundo", "Moeda de Sepultura Antiga"], "effect": "permite conversar com espíritos de mortos no mar em um raio de 12 metros. Concede +1d6 em Sensibilidade para percebê-los e interpretar suas mensagens.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-033.svg"}, {"id": "potion-034", "number": 34, "level": 2, "name": "Poção do Sangue Ígneo", "ingredients": ["Poção da Brasa Marinha", "Escama de Dragão Vulcânico"], "effect": "+1d6 em Resistência e +1d8 de dano de fogo nos ataques corpo a corpo bem-sucedidos, limitado a uma ativação por turno.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-034.svg"}, {"id": "potion-035", "number": 35, "level": 2, "name": "Poção do Rastro do Caçador", "ingredients": ["Poção do Predador", "Terra de Pegada Primordial"], "effect": "+1d6 em Sensibilidade para rastrear e +1d4 em Força. Permite identificar rastros de até 24 horas.", "duration": "15 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-035.svg"}, {"id": "potion-036", "number": 36, "level": 2, "name": "Poção da Correnteza Livre", "ingredients": ["Poção dos Pulmões Marinhos", "Pedra de Cachoeira"], "effect": "respiração aquática, +1d6 em Agilidade e deslocamento aquático dobrado.", "duration": "30 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-036.svg"}, {"id": "potion-037", "number": 37, "level": 2, "name": "Poção da Visão da Verdade", "ingredients": ["Poção do Luar Revelador", "Olho de Peixe-Espelho"], "effect": "+1d6 em Sensibilidade e capacidade de identificar ilusões, criaturas invisíveis e rastros mágicos de nível I ou II em um raio de 10 metros.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-037.svg"}, {"id": "potion-038", "number": 38, "level": 2, "name": "Poção da Imobilização", "ingredients": ["Poção da Paralisia Breve", "Raiz de Cipó Afogado"], "effect": "causa 2d6 de dano tóxico. Na falha em Resistência CD 15, o alvo fica imobilizado por 2 rodadas, sem deslocamento e sem ações físicas.", "duration": "2 rodadas.", "use": "arremessar a até 6 metros ou revestir uma arma. Exige acerto.", "icon": "/icons/arkanis/potions/potion-038.svg"}, {"id": "potion-039", "number": 39, "level": 2, "name": "Poção da Descarga Trovejante", "ingredients": ["Poção da Centelha", "Fragmento de Relâmpago Aprisionado"], "effect": "causa 2d8 de dano elétrico. Na falha em Resistência CD 15, o alvo perde sua próxima ação.", "duration": "imediata; incapacitação por 1 rodada.", "use": "arremessar a até 8 metros. Exige acerto.", "icon": "/icons/arkanis/potions/potion-039.svg"}, {"id": "potion-040", "number": 40, "level": 2, "name": "Poção da Mente Blindada", "ingredients": ["Poção da Mente Serena", "Espinho de Rosa Selvagem"], "effect": "+1d6 em Presença para resistir a manipulação mental, medo e encantamentos. Neutraliza efeitos comuns de medo de nível I.", "duration": "15 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-040.svg"}, {"id": "potion-041", "number": 41, "level": 2, "name": "Elixir do Fôlego Solar", "ingredients": ["Poção do Vigor das Águas", "Semente de Girassol Áureo"], "effect": "recupera 2d8 PV e 1d10 Mana. Também concede +1d6 em Resistência para esforços físicos.", "duration": "recuperação imediata; bônus por 10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-041.svg"}, {"id": "potion-042", "number": 42, "level": 2, "name": "Poção do Pavor Profundo", "ingredients": ["Poção do Terror Noturno", "Lágrima de Banshee"], "effect": "o alvo testa Resistência CD 15. Na falha, sofre -1d6 em Presença e não consegue se aproximar voluntariamente da origem do medo nem atacá-la.", "duration": "2 rodadas.", "use": "arremessar a até 8 metros. Exige acerto.", "icon": "/icons/arkanis/potions/potion-042.svg"}, {"id": "potion-043", "number": 43, "level": 2, "name": "Poção da Aparência Incerta", "ingredients": ["Poção da Pele Mutável", "Flor do Entre-Mundos"], "effect": "+1d6 em Presença para disfarces e atuação. O corpo adquire contornos etéreos e pode ignorar até 1d6 de dano de um único ataque físico.", "duration": "5 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-043.svg"}, {"id": "potion-044", "number": 44, "level": 2, "name": "Poção da Arrancada Relâmpago", "ingredients": ["Poção dos Pés Velozes", "Chifre de Antílope Relâmpago"], "effect": "+1d6 em Agilidade e +3 metros de deslocamento terrestre.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-044.svg"}, {"id": "potion-045", "number": 45, "level": 2, "name": "Poção da Carapaça Viva", "ingredients": ["Poção da Pele-Rocha", "Carapaça de Caranguejo-Rei"], "effect": "+1d6 em Resistência e redução fixa de 3 pontos de dano físico por ataque recebido, depois da armadura.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-045.svg"}, {"id": "potion-046", "number": 46, "level": 2, "name": "Poção da Purificação Profunda", "ingredients": ["Poção da Limpeza Arcana", "Lágrima de Unicórnio"], "effect": "recupera 1d8 PV e remove um veneno, maldição ou outro efeito mágico negativo de nível I ou II.", "duration": "imediata.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-046.svg"}, {"id": "potion-047", "number": 47, "level": 2, "name": "Poção do Segundo Alongado", "ingredients": ["Poção do Instante Dilatado", "Areia do Tempo Perdido"], "effect": "+1d6 diretamente em Reflexos. Aumenta a velocidade de reação, mas não concede turnos extras.", "duration": "3 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-047.svg"}, {"id": "potion-048", "number": 48, "level": 2, "name": "Poção do Duplo Ilusório", "ingredients": ["Poção da Miragem Colorida", "Fragmento de Espelho Astral"], "effect": "cria uma duplicata ilusória do usuário. Antes de cada ataque contra ele, role 1d4: com resultado 1, o ataque atinge a duplicata, que desaparece.", "duration": "3 rodadas ou até a duplicata ser atingida.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-048.svg"}, {"id": "potion-049", "number": 49, "level": 2, "name": "Poção do Salto da Águia", "ingredients": ["Poção da Queda Suave", "Fragmento de Pedra-Céu"], "effect": "+1d6 em Agilidade para acrobacias, saltos horizontais de até 6 metros e redução de 2d10 do dano por queda.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-049.svg"}, {"id": "potion-050", "number": 50, "level": 2, "name": "Poção da Luz Sonora", "ingredients": ["Poção da Luz Serena", "Cristal de Eco"], "effect": "+1d6 em Sensibilidade. Detecta movimentos de criaturas e objetos em um raio de 12 metros por meio de pulsos luminosos e sonoros, inclusive na escuridão comum.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-050.svg"}, {"id": "potion-051", "number": 51, "level": 2, "name": "Poção da Cura Profunda", "ingredients": ["Poção da Renovação", "Casca de Árvore-Coração"], "effect": "recupera 3d10 PV e concede +1d6 em Resistência.", "duration": "cura imediata; bônus por 5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-051.svg"}, {"id": "potion-052", "number": 52, "level": 2, "name": "Poção da Hibernação Glacial", "ingredients": ["Poção do Gelo Vivo", "Sangue de Verme da Geada"], "effect": "coloca o usuário em hibernação. Ele não pode agir, mas recebe apenas metade do dano físico, arredondado para baixo, e suas necessidades de ar e água ficam magicamente reduzidas.", "duration": "até 1 hora ou até ser despertado por um aliado usando uma ação.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-052.svg"}, {"id": "potion-053", "number": 53, "level": 2, "name": "Poção do Magnetismo Estelar", "ingredients": ["Poção da Faísca Cósmica", "Limalha de Ferro Estelar"], "effect": "+1d6 em Inteligência para controlar campos magnéticos. Pode atrair ou mover até 5 kg de metal solto a até 6 metros. Um objeto segurado exige teste oposto à Força do portador.", "duration": "5 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-053.svg"}, {"id": "potion-054", "number": 54, "level": 2, "name": "Poção do Sonho Presságio", "ingredients": ["Poção do Sono Guiado", "Casca de Salgueiro Chorão"], "effect": "durante o sono, o Mestre revela uma visão simbólica de um perigo ou acontecimento possível. Ao despertar, o usuário recebe +1d6 em Inteligência para interpretar a visão.", "duration": "1 hora de sono; bônus por 10 minutos após despertar.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-054.svg"}, {"id": "potion-055", "number": 55, "level": 2, "name": "Poção do Voo Breve", "ingredients": ["Poção da Leveza Etérea", "Escama de Serpente Celeste"], "effect": "permite voar até 6 metros por rodada e concede +1d6 em Agilidade para manobras aéreas.", "duration": "3 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-055.svg"}, {"id": "potion-056", "number": 56, "level": 2, "name": "Poção das Memórias da Madeira", "ingredients": ["Poção da Voz do Bosque", "Musgo de Naufrágio"], "effect": "+1d6 em Sensibilidade. Permite extrair de uma árvore ou objeto antigo de madeira um fragmento de memória relacionado a acontecimentos que presenciou.", "duration": "10 minutos.", "use": "beber e tocar o objeto.", "icon": "/icons/arkanis/potions/potion-056.svg"}, {"id": "potion-057", "number": 57, "level": 2, "name": "Poção do Escudo Devorador", "ingredients": ["Poção da Barreira Nula", "Obsidiana Sangrenta"], "effect": "cria uma barreira que absorve 2d10 de dano mágico total.", "duration": "4 rodadas ou até consumir toda a absorção.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-057.svg"}, {"id": "potion-058", "number": 58, "level": 2, "name": "Poção da Névoa do Eclipse", "ingredients": ["Poção da Escuridão", "Esporo de Névoa Verde"], "effect": "cria uma névoa mágica em um raio de 4 metros. Criaturas incapazes de enxergar através dela sofrem -1d6 nas rolagens de ataque.", "duration": "4 rodadas.", "use": "arremessar a até 8 metros.", "icon": "/icons/arkanis/potions/potion-058.svg"}, {"id": "potion-059", "number": 59, "level": 2, "name": "Poção do Santuário Espiritual", "ingredients": ["Poção da Alma Protegida", "Casulo de Ostra Fantasma"], "effect": "+1d6 em Presença para resistir a influências espirituais. Uma única vez, absorve até 1d8 de dano espiritual.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-059.svg"}, {"id": "potion-060", "number": 60, "level": 2, "name": "Poção da Memória do Local", "ingredients": ["Poção do Eco do Passado", "Lágrima de Espírito Astral"], "effect": "+1d6 em Inteligência para investigar acontecimentos antigos. Revela uma cena fragmentada ocorrida no local nos últimos 7 dias.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-060.svg"}, {"id": "potion-061", "number": 61, "level": 3, "name": "Elixir da Restauração Total", "ingredients": ["Poção da Cura Profunda", "Poção da Purificação Profunda"], "effect": "recupera 4d10 PV, remove venenos e maldições de nível I ou II e concede +1d8 em Resistência. Não recupera membros perdidos nem ressuscita personagens.", "duration": "recuperação imediata; bônus por 5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-061.svg"}, {"id": "potion-062", "number": 62, "level": 3, "name": "Elixir do Desaparecimento", "ingredients": ["Poção da Presença Apagada", "Poção da Névoa do Eclipse"], "effect": "concede invisibilidade completa à visão comum e +1d8 em Agilidade para testes de furtividade. O personagem ainda pode produzir ruídos e deixar pegadas. A invisibilidade termina se realizar um ataque ofensivo.", "duration": "5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-062.svg"}, {"id": "potion-063", "number": 63, "level": 3, "name": "Elixir do Testemunho dos Abismos", "ingredients": ["Poção do Diálogo dos Afogados", "Poção da Memória do Local"], "effect": "+1d8 em Sensibilidade. Permite conversar com espíritos marinhos e observar fragmentos de acontecimentos ocorridos em uma região submersa nos últimos 7 dias.", "duration": "15 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-063.svg"}, {"id": "potion-064", "number": 64, "level": 3, "name": "Poção do Equilíbrio Elemental", "ingredients": ["Poção do Sangue Ígneo", "Poção da Hibernação Glacial"], "effect": "+1d8 em Resistência e redução de 1d8 de dano por fogo ou gelo a cada ataque recebido.", "duration": "5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-064.svg"}, {"id": "potion-065", "number": 65, "level": 3, "name": "Elixir do Rastreador Arcano", "ingredients": ["Poção do Rastro do Caçador", "Poção da Visão da Verdade"], "effect": "+1d8 em Sensibilidade e +1d6 em Inteligência para investigação. Permite detectar rastros de até 48 horas e identificar disfarces e ilusões mágicas de nível I ou II.", "duration": "30 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-065.svg"}, {"id": "potion-066", "number": 66, "level": 3, "name": "Elixir da Travessia Fluida", "ingredients": ["Poção da Correnteza Livre", "Poção do Voo Breve"], "effect": "permite respirar debaixo d'água, concede +1d8 em Agilidade e aumenta o deslocamento aquático em 4 metros. Também permite voar até 6 metros por rodada.", "duration": "respiração aquática e agilidade por 30 minutos; voo por 5 rodadas após a ingestão.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-066.svg"}, {"id": "potion-067", "number": 67, "level": 3, "name": "Frasco da Prisão Elétrica", "ingredients": ["Poção da Imobilização", "Poção da Descarga Trovejante"], "effect": "causa 3d8 de dano elétrico. O alvo atingido testa Resistência CD 18; na falha, fica paralisado por 2 rodadas. No sucesso, sofre somente o dano.", "duration": "dano imediato; paralisia por 2 rodadas.", "use": "arremessar a até 8 metros. Exige acerto.", "icon": "/icons/arkanis/potions/potion-067.svg"}, {"id": "potion-068", "number": 68, "level": 3, "name": "Poção do Temor Dominado", "ingredients": ["Poção da Mente Blindada", "Poção do Pavor Profundo"], "effect": "concede +1d8 em Presença para resistir ao medo e a efeitos mentais. Uma vez durante a duração, pode escolher um alvo a até 10 metros. Se ele falhar em Resistência CD 18, sofre -1d8 em Presença e não consegue se aproximar do usuário.", "duration": "proteção por 5 rodadas; medo causado por 3 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-068.svg"}, {"id": "potion-069", "number": 69, "level": 3, "name": "Elixir do Ímpeto Solar", "ingredients": ["Elixir do Fôlego Solar", "Poção da Arrancada Relâmpago"], "effect": "recupera 2d8 Mana imediatamente, concede +1d8 em Agilidade, +1d8 em Resistência e aumenta o deslocamento terrestre em 4 metros.", "duration": "recuperação imediata; bônus por 5 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-069.svg"}, {"id": "potion-070", "number": 70, "level": 3, "name": "Poção das Muitas Faces", "ingredients": ["Poção da Aparência Incerta", "Poção do Duplo Ilusório"], "effect": "permite alterar a aparência e concede +1d8 em Presença para disfarces. Cria três duplicatas ilusórias. Sempre que alguém atacar o usuário, role 1d4: apenas o resultado 1 identifica o verdadeiro inicialmente. Uma duplicata desaparece quando atingida; reduza o dado de seleção conforme o número de imagens restantes.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-070.svg"}, {"id": "potion-071", "number": 71, "level": 3, "name": "Elixir do Bastião Arcano", "ingredients": ["Poção da Carapaça Viva", "Poção do Escudo Devorador"], "effect": "concede +1d8 em Resistência, reduz 5 pontos de dano físico recebido por ataque após a armadura e cria uma barreira que absorve até 3d10 de dano mágico total.", "duration": "5 rodadas ou até a barreira mágica ser consumida.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-071.svg"}, {"id": "potion-072", "number": 72, "level": 3, "name": "Elixir do Pressentimento Rápido", "ingredients": ["Poção do Segundo Alongado", "Poção do Sonho Presságio"], "effect": "+1d8 diretamente em Reflexos. Uma vez durante a duração, o usuário pode obrigar um inimigo a repetir uma rolagem de ataque contra ele, utilizando o segundo resultado.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-072.svg"}, {"id": "potion-073", "number": 73, "level": 3, "name": "Poção dos Ecos da Floresta", "ingredients": ["Poção da Luz Sonora", "Poção das Memórias da Madeira"], "effect": "+1d8 em Sensibilidade e +1d6 em Inteligência para investigação. Detecta movimentos em um raio de 15 metros e permite consultar uma lembrança preservada pela vegetação nos últimos 7 dias.", "duration": "15 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-073.svg"}, {"id": "potion-074", "number": 74, "level": 3, "name": "Elixir da Órbita Estelar", "ingredients": ["Poção do Magnetismo Estelar", "Poção da Faísca Cósmica"], "effect": "permite controlar até três pequenos objetos metálicos que orbitam o usuário. Uma vez por rodada, pode lançar um deles contra um alvo a até 10 metros, realizando um ataque contra Reflexos. Cada impacto causa 2d8 de dano mágico e 1d8 de dano elétrico. Cada objeto pode ser lançado uma única vez.", "duration": "4 rodadas.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-074.svg"}, {"id": "potion-075", "number": 75, "level": 3, "name": "Elixir do Pacto dos Espíritos", "ingredients": ["Poção do Santuário Espiritual", "Poção do Diálogo dos Afogados"], "effect": "cria uma área de proteção espiritual de 6 metros de raio. Espíritos hostis precisam superar Resistência CD 18 para atravessar a barreira. O usuário recebe +1d8 em Presença para comunicação e resistência espiritual e pode conversar com espíritos aquáticos próximos.", "duration": "10 minutos.", "use": "beber.", "icon": "/icons/arkanis/potions/potion-075.svg"}]$potions$::jsonb)
on conflict(id) do update set name=excluded.name,data=excluded.data;
-- Catalogued potions are not custom items. Existing RLS still governs who can edit the bag.
do $$ declare definition text; begin
 definition=pg_get_functiondef('private.campaign_custom_item_guard()'::regprocedure);
 if strpos(definition,'-- arkanis49 potions')=0 then
 execute regexp_replace(definition,'\mbegin\M',$guard$begin
 -- arkanis49 potions
 if exists(select 1 from public.characters ch join public.rpg_systems rs on rs.id=ch.rpg_system_id join public.arkanis_potions p on p.name=new.data->>'name' where ch.id=new.character_id and rs.slug='arkanis' and p.data->>'icon'=new.data->>'image_path') then return new; end if;
 $guard$,'i');
 end if;
end $$;

create or replace function private.arkanis49_progression() returns trigger language plpgsql security definer set search_path='' as $$
declare s jsonb=new.system_data; race text=s->>'race_id'; apt text; rank integer; res integer; modifier integer; die integer; lv integer; total integer; rolls jsonb; roll jsonb; method text; previous jsonb;
begin
 if (select slug from public.rpg_systems where id=new.rpg_system_id)<>'arkanis' then return new;end if;
 apt=case race when 'human' then 'logico' when 'dwarf' then 'mecanico' when 'harpy' then 'percepcao' when 'demon' then 'intimidacao' end;
 rank=case when race in ('harpy','demon') then 2 else 1 end;
 if apt is not null then s=jsonb_set(s,array['aptitudes',apt],to_jsonb(greatest(coalesce((s->'aptitudes'->>apt)::integer,0),rank)));end if;
 -- Legacy records keep their stored maximum until opened with the new editor.
 if s ? 'hit_point_method' then
 select case when hit_point_method='rolled' then 'rolled' else 'maximum' end into method from public.campaign_rules where campaign_id=new.campaign_id;
 method=coalesce(method,'maximum');
 if s->>'hit_point_method' is distinct from method then raise exception 'A regra de PV mudou. Reabra a ficha antes de salvar.' using errcode='40001';end if;
 lv=(s->>'level')::integer;
 if lv not between 1 and 100 then raise exception 'Nível inválido.';end if;
 die=case race when 'orc' then 12 when 'dwarf' then 10 when 'triton' then 10 else 8 end;
 res=(s->'attributes'->>'res')::integer + (s->'attribute_adjustments'->>'res')::integer + case race when 'dwarf' then 2 when 'triton' then 1 when 'demon' then 1 else 0 end + case when race='human' and s->>'human_attribute'='res' then 1 else 0 end + case when s->'arkano'->>'body'='10' then 1 else 0 end;
 modifier=case when res<=2 then -5 when res<=5 then -4 when res<=8 then -3 when res<=11 then -2 when res<=14 then -1 when res<=16 then 0 when res<=19 then 1 when res<=22 then 2 when res<=25 then 3 when res<=28 then 4 else 5 end;
 total=0;
 if method='rolled' then
  rolls=s->'pv_rolls'->race;
  if jsonb_typeof(rolls) is distinct from 'array' or jsonb_array_length(rolls)<lv or jsonb_array_length(rolls)>100 then raise exception 'Role os PV dos níveis pendentes.';end if;
  for roll in select value from jsonb_array_elements(rolls) loop
   if jsonb_typeof(roll) is distinct from 'number' or (roll::text)::numeric<>trunc((roll::text)::numeric) or (roll::text)::integer not between 1 and die then raise exception 'Dado de PV inválido.';end if;
  end loop;
  select coalesce(sum(value::text::integer),0) into total from jsonb_array_elements(rolls) with ordinality where ordinality<=lv;
  select system_data->'pv_rolls'->race into previous from public.characters where id=new.id;
  if previous is not null and jsonb_typeof(previous)='array' and exists(select 1 from jsonb_array_elements(previous) with ordinality p where rolls->(p.ordinality::integer-1) is distinct from p.value) then raise exception 'Rolagens de PV já registradas devem ser preservadas.';end if;
 else total=die*lv;
 end if;
 total=greatest(1,total+lv*(case when race='orc' then res else modifier end)+case when race='orc' then 8 else 0 end);
 s=jsonb_set(s,'{hp_max}',to_jsonb(total));
 s=jsonb_set(s,'{hp_current}',to_jsonb(least((s->>'hp_current')::integer,total)));
 end if;
 new.system_data=s;
 return new;
end $$;
revoke all on function private.arkanis49_progression() from public,anon,authenticated;
drop trigger if exists zy_arkanis49_progression on public.characters;
create trigger zy_arkanis49_progression before insert or update on public.characters for each row execute function private.arkanis49_progression();
notify pgrst,'reload schema';
commit;
